INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', 'AWM-01', 'REF-00468', NULL, 1, 1, NULL, NULL, '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2', 'Not run in this batch, by choice: the batch''s scope was the turning and passage figures of this report and the three non-English code readings. Backward: the bibliography (PDF pages 159-173, persisted in e664fb2f8174f4f8-full-text.txt) is ready to mine and includes the Canadian UDI study and BS 8300 research the report compares against. Forward: no citation-index query was made. The deferral is assigned to the next batch (GAP-025 mechanism).');
INSERT INTO "evidence_sources" ("ref_id", "source_type", "author_count", "author_count_is_complete", "first_author_last", "first_author_first", "is_corporate_primary", "author_display", "pub_year", "pub_year_note", "pub_title", "pub_subtitle", "chapter_title", "original_title", "lang_detected", "lang_detection_method", "pub_title_en", "pub_subtitle_en", "chapter_title_en", "journal_name_en", "translation_method", "translation_reviewed", "journal_name", "journal_abbrev", "volume", "issue", "pages_start", "pages_end", "article_number", "publisher", "publisher_location", "edition", "book_title", "series", "series_number", "report_number", "institution", "standard_number", "doi", "pmid", "pmcid", "isbn", "issn", "url", "url_accessed", "handle", "local_id", "tier", "evidence_type", "jurisdiction", "co1_provenance", "co1_source_type", "synthesis_attribution_required", "metadata_quality", "verification_status", "doi_resolution_outcome", "bpc_shorthand", "bpc_note", "grey_flag", "grey_reason", "verification_note", "prior_expectation", "search_queries_used", "derivation_chain", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "verified_by_tool", "last_verified_at", "verification_attempt_count", "superseded_by_ref_id", "pages", "pub_month", "language", "subtype", "citation_count", "url_resolution_outcome", "url_last_fetched", "url_match_similarity", "metadata_integrity_status", "metadata_integrity_detail", "code_currency_status", "code_currency_verified_at", "code_currency_verified_by_session", "code_currency_notes", "scope", "data_capture_status", "citation_mining_status", "processing_blocked_reason", "standard_number_note", "author_display_note", "publisher_note", "verification_disposition", "verification_method", "verification_closure_reason") VALUES ('REF-00468', 'report', NULL, 0, NULL, NULL, 0, NULL, 2010, NULL, 'Anthropometry of Wheeled Mobility Project: Final Report', NULL, NULL, NULL, 'en', 'read on the title page, credits page and throughout the extracted text', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'University at Buffalo, Center for Inclusive Design and Environmental Access', 'Buffalo, NY', NULL, NULL, NULL, NULL, NULL, 'Center for Inclusive Design and Environmental Access (IDeA), School of Architecture and Planning, University at Buffalo, The State University of New York', NULL, NULL, NULL, NULL, NULL, NULL, 'https://idea.ap.buffalo.edu/wp-content/uploads/sites/110/2020/01/AnthropometryofWheeledMobilityProject_FinalReport.pdf', '2026-11-06', NULL, NULL, 3, 'grey', 'US', NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'NO-MATCH', NULL, NULL, 1, 'US federal contract research report prepared for the US Access Board (contract TPD-ABA-07-C-001, initially funded by NIDRR grant H133E99005), dated 31 December 2010, hosted by the authoring centre; not peer reviewed. A primary measurement study of wheeled mobility device users, so its figures are measurements, not a committee assertion.', NULL, NULL, NULL, NULL, NULL, '2026-11-06 04:32', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, 1, NULL, '173', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'intrinsic', 'pending', 'deferred', NULL, NULL, NULL, NULL, 'CLOSED', 'direct-render', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-11-06-pipel-REF-00468-MOB', 'REF-00468', 'MOB', '495 wheeled mobility device users (manual wheelchair, conventional powered wheelchair and scooter users) measured in a laboratory mock-up hallway; recruited in Buffalo and suburbs (351), Pittsburgh (100) and Ithaca (44); powered wheelchair users deliberately oversampled', 495, 'EXACT', 'EXACT on the population served (people who use wheelchairs and scooters). Two limits are written so the grade is not read as representativeness: the report says the sample is not proportional to national estimates of device type (powered chairs oversampled), and the turning tasks were done in a built mock-up, so a person using a wheelchair in a real corridor with a companion or a door swing is outside it. Scooter users are in the sample and are a different device class from wheelchairs; the report separates them in its tables.', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2', 'REF-00468', NULL);
