INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (96, 'REF-00468', '360-degree turn', 'EN', 'Section 3.3.13, report p. 61 (PDF p. 65)', 'Less than 50% of our manual and powered wheelchair users completed a 360-degree turn within the United States standard turning diameter (Figure 3-12).', NULL, '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (97, 'REF-00468', 'turning clearance', 'EN', 'Section 4.3.5, report p. 93 (PDF p. 97)', 'This turning clearance is applicable for exterior and interior circulation, aisles in seating areas, ramps and other locations.', NULL, '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (98, 'REF-00468', '90-degree turning width', 'EN', 'Section 4.3.5.1, report p. 93 (PDF p. 97)', 'We recommend revising the ADA-ABA standard for 90-degree turning width to 1000 mm (39 in.) which would accommodate at least 95% of our sample.', NULL, '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2');
INSERT INTO "source_slug_links" ("ref_id", "slug", "local_ref_id", "created_at", "created_by_session", "updated_at", "updated_by_session", "relevance_note") VALUES ('REF-00468', 'accessible-circulation-geometry', 'AWM-01', '2026-11-06 04:32', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:32', 'session_2026-11-06-pipeline-batch-2', NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (201, NULL, 5, NULL, 'EN', 1, 'co1', 'intrinsic', 'disabled people''s organisation guidance wheelchair users doorway clear width turning space lived experience participatory design', NULL, 'web', 'scoping', NULL, 15, 15, 0, 'none', NULL, NULL, 0, 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:31', 'No Co-1 source. Fifteen results: UK housing-association and local-authority wheelchair housing design guides (HousingLIN, Camden, Southwark), a Scottish government consultation, Massachusetts 521 CMR 6, a Texas TAS page, a South African SANS 10400 page, an ADA figures page and a Wiley excerpt. They state 1500 mm turning space, 840 to 900 mm door clear opening and 1200 mm hallways, all from code or planning-guidance bodies, none from a disabled persons organisation. R14: a WELL-FORMED query for the question asked; the long natural-language shape returned code pages, so the zero Co-1 yield is a wrong-index and a query-shape result together, not proof of absence. A targeted DPO search (Disability Rights UK, Scope, Centre for Accessible Environments) is not done by this batch and stays open. Results listed in the transcript only (WebSearch leaves no payload); the I5 ledger holds the query.', 0, 'Stated in the session transcript before the search ran: 5-10 results, mostly code-body or consultancy pages; no result genuinely co-produced by disabled people with a measured dimension; at best a few disability-organisation guides (grey, tier 3).', 'planned', NULL, NULL, '2026-11-06 04:31', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (202, NULL, 5, NULL, 'EN', 2, 'sr_meta', 'intrinsic', 'systematic review wheelchair manoeuvring space requirements doorway width turning space anthropometry', NULL, 'web', 'scoping', NULL, 10, 10, 0, 'partial', NULL, NULL, 0, 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:31', 'No systematic review of manoeuvring space. Ten results: the Steinfeld 2010 review (informahealthcare, DOI 10.1080/10400430903520280, already candidate 151), a Stanford RESNA 2010 worksheet, five pages of the Anthropometry of Wheeled Mobility Project Final Report transcribed on corada.com, ISO 7176-5 (a measurement standard), a CORE PDF (403 on retrieval) and a 2019 International Journal of Occupational Safety and Ergonomics paper on wheelchair-user anthropometry (a systematic review of body and device size, not of space requirements). The surprise is the report: a primary measurement study of 495 wheeled mobility users, found through its transcription, and followed at the next search. The prior (nothing new) was wrong. || CORRECTED 2026-11-06: The journal of the 2019 paper (DOI 10.1080/10803548.2019.1567974) is not stated in the search result; the name given above was inferred from the DOI prefix and is withdrawn.', 0, 'Stated in the session transcript before the search ran: 0-2 reviews, probably the Steinfeld 2010 and Koontz 2010 papers already staged; nothing new expected.', 'planned', NULL, NULL, '2026-11-06 04:32', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (203, NULL, 5, NULL, 'EN', NULL, NULL, NULL, '"Anthropometry of Wheeled Mobility Project" Final Report IDeA Center Access Board pdf || retrieved https://idea.ap.buffalo.edu/wp-content/uploads/sites/110/2020/01/AnthropometryofWheeledMobilityProject_FinalReport.pdf', NULL, 'web', 'scoping', NULL, 10, 10, 1, 'saturated', NULL, NULL, 0, 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:32', 'Lookup of a source surfaced by exec 202. The first result is the PDF on idea.ap.buffalo.edu; the others are corada.com transcriptions of its sections, an Access Board page on wheelchair seat height, and a humancentereddesign.org library entry. Retrieved 2026-11-06 (HTTP 200, 14,986,049 bytes, 173 pages, sha256 e664fb2f8174f4f8) and admitted as REF-00468, the stash id that already held this title (the stash row carries an unrelated Husbanken URL: the GAP-008 shuffled-field defect). The corada transcription pages (da321ad57f7fc3f5.html, 41510aa497941b7d.html) were retrieved first and are not the source of any row.', 0, 'Stated in the session transcript before the search ran: at least one result hosting the PDF on the Access Board or the IDeA Center site, about 80 percent likely.', 'incidental', NULL, NULL, '2026-11-06 04:32', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL);
INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (10, 'REF-00468', 'catalogue', 12, NULL, 'full', 173, 173, 'bae3334434e4025dbc3e17311e4ecb28626f986f3a0eaceebc180e39a1072da8', 0, 'pre-screen', 'Derived text of all 173 pages (e664fb2f8174f4f8-full-text.txt). NOT read end to end. Read in full: PDF pages 16-17 (sampling), 61-65 (turn findings), 90-101 (implications for turning clearance); located by keyword and read in part: pages 34, 48, 67, 90, 92 (door, force). Zero hits on the whole text for light reflectance, LRV, luminance contrast, headroom, overhead or vertical clearance, colour temperature, reverberation: parameters 7, 8, 10, 11 find no value here. Parameter 9: the report says the clear floor area width informs the minimum clearance for doorways but states no door clear width recommendation; not filed. Parameter 6: p.67 reports maximum grip force of the users (a capacity), not a force a door or control may require; not filed. Parameter 3 and 12: ramps are mentioned only in passing on pages 90-100. Filed: turning and passage widths at turns (parameters 4 and 5). Tables are cell sequences without row labels in the text, so only sentence-form figures are filed. Figures are images and unread.', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2');
INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (11, 'REF-01028', 'catalogue', 12, NULL, 'full', NULL, NULL, 'b9353457a95a925b4b646e2c0263d35bdc1b973964f28645110569d14717047a', 0, 'pre-screen', 'BOE consolidated text of Orden TMA/851/2021 (visible-text extraction of the web page, batch 23). The order governs urbanised PUBLIC SPACE (pedestrian routes, street furniture, public toilet cabins), not building interiors, so building corridor, door and headroom values are not here and the rows carry that setting. Read in full: articles 5, 28, 34, 39 (and the 4 paragraphs after art 39). Keyword screen over the rest (contraste, luminancia, reflectancia, LRV, fuerza, esfuerzo, newton, anchura libre, altura libre, círculo, diámetro): other hits are 2,20 m free height repeated in arts 6, 7, 14 (not refiled), 1,50 m circles at play areas and drinking fountains (arts 8, 27; not refiled), and qualitative contrast. Parameters 4, 5, 6, 9, 11 filed; parameter 8 absent (no LRV), parameter 6 absent for toilet controls. Parameters 3 and 12 (ramps, art 14) are already held from this source. Parameters 7 and 10: no hits. Not read end to end.', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2');
INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (12, 'REF-01031', 'catalogue', 12, NULL, 'full', 22, 22, 'e61147623cbd9d61ea5ff3e25e97c24b00a4d8314d9414c49120c87e967adc42', 0, 'pre-screen', 'Derived text of all 22 pages of Annex 1 (batch 23). Read in full: item 6 (entrances, pages 3-4), item 7 (corridors and passages, pages 4-5, including obstacles and clear height), and the accessible-toilet clauses on page 11. Located by keyword and not read in full: the other items (parking, elevators, stairs, bathrooms, rooms, pages 1-2, 6-10, 12-22). Parameters 4, 5, 9, 11 filed. The annex states no force (no newton or kilogram figure for doors) and no luminance or light reflectance contrast value: parameters 6 and 8 find no value, and no absence row was filed because the annex was not read end to end. Parameters 7 and 10: no hits. Elevator door widths (0.8 m, 0.9 m), the 1.5 m by 1.5 m passing zones on access routes and the competition-wheelchair figures (1.2 m door, 1.5 m by 1.5 m turning) are stated and not filed. The 0.9 m access-route-to-door figure of item 1 is the route width of 1.2 m already filed under parameter 3.', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2');
INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (13, 'REF-01032', 'catalogue', 12, NULL, 'partial', 5, 20, 'de24554e5ad496f16ff1c0f94a1f6ec0b477b3f9948626dac38d0ed054e06933', 0, 'pre-screen', 'Derived text of 5 of the 20 pages of the Diario da Republica issue (pages 1, 2, 9, 10, 20; batch 23). Pages 9 and 10 read in full: sections 2.2 (atria), 2.3 (landings, galleries, corridors), 2.5 (ramps), 2.6 (lifts). Filed: parameters 9 (2.2.3) and 4 (2.3.1, 2.3.2). Parameter 5: 2.2.1, 2.2.2 and 2.3.3 require a manoeuvre zone for a 360-degree rotation, but the dimension sits in section 4.4, which these pages do not hold, so no turning figure is filed. Parameters 6, 7, 8, 10, 11: not on the pages held; NOT examined, because most of the decree is not in the text. The remaining 15 pages are unread.', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2');
INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (14, 'REF-01031', 'catalogue', 12, NULL, 'full', 22, 22, 'e61147623cbd9d61ea5ff3e25e97c24b00a4d8314d9414c49120c87e967adc42', 0, 'pre-screen', 'Second reading, same day; replaces the first scan note of this source where they differ. CORRECTION: the first note ended with a sentence about a 0.9 m access-route figure of item 1 being filed under parameter 3. That sentence is wrong and is withdrawn: item 1 states the access-route clear width as 1.2 m, and nothing from item 1 is filed under parameter 3. The 1.2 m access-route width is now filed under parameter 4 (item 1(a)(1)). Everything else in the first note stands.', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (193, 'REF-00468', NULL, 5, 'MOB', NULL, NULL, NULL, 'US', '360-degree turn in a confined space; whole sample of 495 users', 'numerical', '2500', 'mm', 'The 360-degree turning diameter would have to be increased to 2500 mm (a little over 98 in.) to accommodate our entire study sample.', 'Anthropometry of Wheeled Mobility Project Final Report, section 3.3.13', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '3.3.13', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'PDF page 65 of 173; report page 61', 'skim', 'preliminary', NULL, 'Quantity: diameter that would accommodate every user in the study sample for a 360-degree turn; the report states it against the US standard of 1525 mm, which fewer than half of its manual and powered wheelchair users completed within. A finding about the sample, not a recommended standard. Lens MOB: the report measures wheelchair and scooter users, the population these widths serve [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'finding', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (194, 'REF-00468', NULL, 5, 'MOB', NULL, NULL, NULL, 'US', '360-degree turn; scooter users', 'numerical', '1900', 'mm', 'In fact, the tightest 360 turn performed by a scooter user was 1900 mm (75 in.) in diameter!', 'Anthropometry of Wheeled Mobility Project Final Report, section 3.3.13', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '3.3.13', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'PDF page 65 of 173; report page 61', 'skim', 'preliminary', NULL, 'Quantity: smallest diameter in which any scooter user in the sample completed a 360-degree turn. A measured minimum for one device class, not a requirement. Lens MOB: the report measures wheelchair and scooter users, the population these widths serve [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (195, 'REF-00468', NULL, 4, 'MOB', NULL, NULL, NULL, 'US', 'width of a passage at a 90-degree (L) turn', 'numerical', '1000', 'mm', 'We recommend revising the ADA-ABA standard for 90-degree turning width to 1000 mm (39 in.) which would accommodate at least 95% of our sample.', 'Anthropometry of Wheeled Mobility Project Final Report, section 4.3.5.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '4.3.5.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'PDF page 97 of 173; report page 93', 'skim', 'preliminary', NULL, 'Quantity: passage width at a 90-degree turn; the authors'' recommendation for a standard. Their Figure 4-4 text puts the current ADA requirement at 915 mm and 50 percent of manual and powered chair users needing 850 mm. Whether a width at a turn is parameter 4 or a term of its own is deferred (observation 98). Lens MOB: the report measures wheelchair and scooter users, the population these widths serve [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (196, 'REF-00468', NULL, 4, 'MOB', NULL, NULL, NULL, 'US', 'width of a space bounded by two parallel walls or three walls, 180-degree turn', 'numerical', '1700', 'mm', 'Our findings indicated that a width of 1700 mm (67 in.) would accommodate 95% of manual and power wheelchair users and 90% of the scooter users.', 'Anthropometry of Wheeled Mobility Project Final Report, section 4.3.5.2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '4.3.5.2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'PDF page 99 of 173; report page 95', 'skim', 'preliminary', NULL, 'Quantity: width accommodating 95 percent of manual and powered wheelchair users and 90 percent of scooter users in a 180-degree turn. A finding; the authors note the ADA-ABA has no clearance for this turn and the 1525 mm turning space is used instead. Deferred term as for observation 98. Lens MOB: the report measures wheelchair and scooter users, the population these widths serve [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'finding', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (197, 'REF-00468', NULL, 4, 'MOB', NULL, NULL, NULL, 'US', 'uniform width for a 180-degree turn around an obstacle', 'numerical', '1095', 'mm', 'We recommend using this approach in future ADA-ABA standards with a minimum width of 1095 mm (43 in.) which would accommodate more than 95% of all WhMD users in the sample.', 'Anthropometry of Wheeled Mobility Project Final Report, section 4.3.5.3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '4.3.5.3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'PDF page 100 of 173; report page 96', 'skim', 'preliminary', NULL, 'Quantity: minimum uniform width (entry aisle, turning area depth and egress aisle equal) for a 180-degree turn around an obstacle; the authors'' recommendation. Deferred term as for observation 98. Lens MOB: the report measures wheelchair and scooter users, the population these widths serve [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (198, 'REF-01028', NULL, 4, 'ALL', NULL, NULL, NULL, 'ES', 'accessible pedestrian route in urbanised public space', 'numerical', '1.80', 'm', 'En todo su desarrollo poseerá una anchura libre de paso no inferior a 1,80 m, que garantice el giro, cruce y cambio de dirección de las personas, independientemente de sus características o modo de desplazamiento.', 'Orden TMA/851/2021, article 5.2.b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '5', NULL, '2', 'b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BOE consolidated text, article 5', 'skim', 'preliminary', NULL, 'Quantity: minimum clear width of an accessible pedestrian route (itinerario peatonal accesible), outdoors in public space, not a building corridor. The clause gives the reason: turning, passing and changing direction. Unit as stated (metres, comma decimal in the source). Lens ALL: the clause says ''independientemente de sus características o modo de desplazamiento'' [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (199, 'REF-01028', NULL, 11, 'ALL', NULL, NULL, NULL, 'ES', 'accessible pedestrian route in urbanised public space', 'numerical', '2.20', 'm', 'En todo su desarrollo poseerá una altura libre de paso no inferior a 2,20 m.', 'Orden TMA/851/2021, article 5.2.c', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '5', NULL, '2', 'c', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BOE consolidated text, article 5', 'skim', 'preliminary', NULL, 'Quantity: minimum clear height of an accessible pedestrian route. The same 2,20 m recurs for rest areas (art 6), parks (art 7) and ramps (art 14.7); not filed again (rule 5). Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (200, 'REF-01028', NULL, 5, 'ALL', NULL, NULL, NULL, 'ES', 'in front of the door of an accessible public toilet cabin, outside', 'numerical', '1.50', 'm', 'Contarán con un espacio libre de obstáculos donde pueda inscribirse un círculo de 1,50 m de diámetro, como mínimo, delante de la puerta de acceso y dicho espacio no podrá coincidir, ni con el itinerario peatonal accesible, ni con el área barrida por la apertura de la puerta de la cabina.', 'Orden TMA/851/2021, article 34.2.a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '34', NULL, '2', 'a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BOE consolidated text, article 34', 'skim', 'preliminary', NULL, 'Quantity: minimum diameter of the circle to be inscribed in the obstacle-free space before the cabin door; it may not coincide with the accessible route or the door swing. A circle of this diameter, not stated as a wheelchair turning space in this clause. Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (201, 'REF-01028', NULL, 5, 'ALL', NULL, NULL, NULL, 'ES', 'inside an accessible public toilet cabin, beside the door', 'numerical', '1.50', 'm', 'Junto a la puerta habrá un espacio libre de obstáculos que permita inscribir en toda su altura un círculo de 1,50 m de diámetro mínimo, siendo la altura mínima en el interior de la cabina de 2,20 m.', 'Orden TMA/851/2021, article 34.3.a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '34', NULL, '3', 'a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BOE consolidated text, article 34', 'skim', 'preliminary', NULL, 'Quantity: minimum diameter of the obstacle-free circle inside the cabin, over its full height. The same sentence states the cabin interior height (see the parameter 11 row). Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (202, 'REF-01028', NULL, 11, 'ALL', NULL, NULL, NULL, 'ES', 'inside an accessible public toilet cabin', 'numerical', '2.20', 'm', 'siendo la altura mínima en el interior de la cabina de 2,20 m.', 'Orden TMA/851/2021, article 34.3.a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '34', NULL, '3', 'a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BOE consolidated text, article 34', 'skim', 'preliminary', NULL, 'Quantity: minimum interior height of the cabin. Read from the same sentence as the parameter 5 row inside the cabin. Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (203, 'REF-01028', NULL, 9, 'ALL', NULL, NULL, NULL, 'ES', 'access door of an accessible public toilet cabin', 'numerical', '80', 'cm', 'La puerta de acceso será abatible hacia el exterior o corredera, tendrá una anchura libre de paso mínima de 80 cm y su mecanismo de cierre será de fácil manejo, posibilitando su apertura desde fuera en caso de emergencia.', 'Orden TMA/851/2021, article 34.2.b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '34', NULL, '2', 'b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BOE consolidated text, article 34', 'skim', 'preliminary', NULL, 'Quantity: minimum clear passage width of the cabin door. Unit as stated (centimetres). Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (204, 'REF-01028', NULL, 6, 'ALL', NULL, NULL, NULL, 'ES', 'opening mechanism of a street litter bin or container', 'numerical', '25', 'N', 'En todo caso el mecanismo de apertura no requerirá una fuerza superior a 25 N y el sistema de cierre será retardado.', 'Orden TMA/851/2021, article 28.b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '28', NULL, NULL, 'b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BOE consolidated text, article 28', 'skim', 'preliminary', NULL, 'Quantity: maximum force to operate the opening mechanism of a litter bin or waste container on the pedestrian route. Not a door; the only force figure in the order. Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (205, 'REF-01028', NULL, 6, 'ALL', NULL, NULL, NULL, 'ES', 'controls in an accessible public toilet cabin', 'absent', NULL, NULL, 'Los mecanismos de accionamiento de lavabos, duchas y mecanismos de descarga de inodoros serán pulsadores de gran superficie accionables con el puño o con el codo, o palancas de fácil manejo y requerirán poco esfuerzo.', 'Orden TMA/851/2021, article 34.3.f', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '34', NULL, '3', 'f', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BOE consolidated text, article 34', 'skim', 'preliminary', NULL, 'Absence: the clause that governs the operating controls of the cabin states poor force qualitatively (poco esfuerzo, little effort) and gives no figure, in an order that gives 25 N for litter bin openings. Found by keyword search (fuerza, esfuerzo, N, newton) over the whole text; the text was not read end to end. Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (206, 'REF-01028', NULL, 8, 'ALL', NULL, NULL, NULL, 'ES', 'temporary works scaffold uprights on a pedestrian route', 'absent', NULL, NULL, 'Todos los montantes verticales u horizontales que delimiten el itinerario estarán recubiertos por materiales protectores frente a golpes y su visibilidad estará garantizada mediante colores de alto contraste.', 'Orden TMA/851/2021, article 39.2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '39', NULL, '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BOE consolidated text, article 39', 'skim', 'preliminary', NULL, 'Absence: contrast is required in words (colores de alto contraste, high-contrast colours) and no light reflectance value or luminance difference is stated. Keyword search over the whole text (contraste, luminancia, reflectancia, LRV) found no figure; the text was not read end to end. Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (207, 'REF-01031', NULL, 9, 'ALL', NULL, NULL, NULL, 'KR', 'entrances and doors that persons with disabilities enter', 'numerical', '0.9', 'm', '출입구(문)은 아래의 그림과 같이 그 통과유효폭을 0.9미터 이상으로 하고,', 'Enforcement Rule of the Act on the Promotion of Convenience for Persons with Disabilities, Seniors and Pregnant Women, Annex 1, item 6(a)(1)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '6', NULL, '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'law.go.kr Annex 1 download, PDF page 3 of 22', 'skim', 'preliminary', NULL, 'Quantity: minimum clear passage width of an entrance door. The same sentence sets the clear distance in front of the door at 1.2 m. Para (2) sets 1.2 m for sports facilities'' doors for competition wheelchair users; not filed. Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
