INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (209, 'REF-01031', NULL, 4, 'ALL', NULL, NULL, NULL, 'KR', 'corridors and passages with rooms on both sides', 'numerical', '1.5', 'm', '에는 1.5미터 이상으로 할 수 있다.', 'Enforcement Rule of the Act on the Promotion of Convenience for Persons with Disabilities, Seniors and Pregnant Women, Annex 1, item 7(a)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '7', NULL, 'a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'law.go.kr Annex 1 download, PDF page 4 of 22', 'skim', 'preliminary', NULL, 'Quantity: width for a corridor with rooms (거실) on both sides; the text says it MAY be set at 1.5 m or more (할 수 있다), a permission, so the comparator records the stated floor only. The quote starts at a line break inside the sentence in the extracted text. Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (210, 'REF-01031', NULL, 11, 'ALL', NULL, NULL, NULL, 'KR', 'above a passage', 'numerical', '2.1', 'm', '통로상부는 바닥면으로부터 2.1미터 이상의 유효높이를 확보해야 한다.', 'Enforcement Rule of the Act on the Promotion of Convenience for Persons with Disabilities, Seniors and Pregnant Women, Annex 1, item 7(라)(3)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '7', NULL, '라', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'law.go.kr Annex 1 download, PDF page 5 of 22', 'skim', 'preliminary', NULL, 'Quantity: minimum clear height above a passage. If an obstacle lies within that height the clause requires a barrier or protective wall at 0.6 m or below. Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (211, 'REF-01031', NULL, 5, 'MOB', NULL, NULL, NULL, 'KR', 'in front of the water closet in a new-build accessible toilet', 'numerical', '1.4', 'm', '이 경우 대변기의 전면에는 휠체어가 회전할 수 있도록 1.4미터×1.4미터 이상의 활동공간을 확보하여야 한다.', 'Enforcement Rule of the Act on the Promotion of Convenience for Persons with Disabilities, Seniors and Pregnant Women, Annex 1, item 8(나)(1)(가)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '8', NULL, '나', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'law.go.kr Annex 1 download, PDF page 11 of 22', 'skim', 'preliminary', NULL, 'Quantity: side of the square activity space (1.4 m by 1.4 m) in front of the water closet so that a wheelchair can turn; stated for newly built toilets. For competition-wheelchair toilets the text states 1.5 m by 1.5 m; not filed. Lens MOB: the clause says 휠체어가 회전할 수 있도록 (so that a wheelchair can turn) [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (212, 'REF-01032', NULL, 9, 'ALL', NULL, NULL, NULL, 'PT', 'entrance and exit doors of buildings and establishments', 'numerical', '0.87', 'm', 'As portas de entrada/saída dos edifícios e estabelecimentos devem ter um largura útil não inferior a 0,87 m', 'Decreto-Lei 163/2006, Annex, item 2.2.3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '2', NULL, '2.2.3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Diario da Republica 1a serie N.o 152, 8 Aug 2006, PDF page 9 of 20', 'skim', 'preliminary', NULL, 'Quantity: minimum clear width of an entrance or exit door, measured between the face of the open leaf and the stop on the opposite side; a door opened to 90 degrees if hinged or pivoting. Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (213, 'REF-01032', NULL, 4, 'ALL', NULL, NULL, NULL, 'PT', 'landings, galleries and corridors', 'numerical', '1.2', 'm', 'Os patamares, galerias e corredores devem possuir uma largura não inferior a 1,2 m.', 'Decreto-Lei 163/2006, Annex, item 2.3.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '2', NULL, '2.3.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Diario da Republica 1a serie N.o 152, 8 Aug 2006, PDF page 9 of 20', 'skim', 'preliminary', NULL, 'Quantity: minimum width of a landing, gallery or corridor. Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (214, 'REF-01032', NULL, 4, 'ALL', NULL, NULL, NULL, 'PT', 'short segments of landings, galleries or corridors, under 1.5 m long and giving no access to side doors', 'numerical', '0.9', 'm', 'Podem existir troços dos patamares, galerias ou corredores com uma largura não inferior a 0,9 m, se o seu comprimento for inferior a 1,5 m e se não derem acesso a portas laterais de espaços acessíveis.', 'Decreto-Lei 163/2006, Annex, item 2.3.2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '2', NULL, '2.3.2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Diario da Republica 1a serie N.o 152, 8 Aug 2006, PDF page 9 of 20', 'skim', 'preliminary', NULL, 'Quantity: reduced width permitted for a short segment. A permission (podem existir), so the comparator records the stated floor only. Lens ALL: the clause names no population [ASSUMPTION: lens is the reader''s filing; ALL is the scope marker for a clause whose own text names no one].', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (215, 'REF-01031', NULL, 4, 'MOB', NULL, NULL, NULL, 'KR', 'access route (접근로) on a site', 'numerical', '1.2', 'm', '휠체어사용자가 통행할 수 있도록 접근로의 유효폭은 1.2미터 이상으', 'Enforcement Rule of the Act on the Promotion of Convenience for Persons with Disabilities, Seniors and Pregnant Women, Annex 1, item 1(a)(1)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '1', NULL, NULL, 'a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'law.go.kr Annex 1 download, PDF page 1 of 22; the quote stops at a line break inside the word (이상으로)', 'skim', 'preliminary', NULL, 'Quantity: minimum clear width of an access route so that wheelchair users can pass (휠체어사용자가 통행할 수 있도록). Paragraph (2) sets 1.5 m by 1.5 m passing zones every 50 m (not filed). Lens MOB: the clause names wheelchair users. Filed after the first scan note of this source was written; see the second scan.', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', 'claim', '>=');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (87, 96, 'NAMES-EXISTING', 'TERM-003', 'The report uses 360-degree turn for the task of rotating a wheelchair or scooter through a full circle within a diameter, and measures it against the US turning-diameter standard of 1525 mm. TERM-003 (turning circle) is defined as space for wheelchair 360 degree rotation. The usage is the same concept; the report adds scooters, which the definition does not exclude.', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (88, 97, 'DEFERRED', NULL, 'Turning clearance in section 4.3.5 is a heading for a family of manoeuvres (circular and T-shaped turning space, L-turn, U-turn around an obstacle), not for the 360 degree rotation TERM-003 names. Whether the family is one term, several, or a tag over existing ones is a definition the owner approves for any new term (OT-2 pattern); not decided here.', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (89, 98, 'DEFERRED', NULL, 'The width a passage needs at a 90 degree turn is a quantity distinct from TERM-002 (corridor width, the width of an accessible circulation route along its length) and from TERM-003. Whether it is a new term, an expression of TERM-002 at a turn, or a condition on it is the owner''s to define; the figures are filed on parameter 4 meanwhile with the setting stated, and this row does not mint a parameter.', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2');
